WITH stamp AS (SELECT clock_timestamp() AS at) INSERT INTO candidate_profiles (full_name,email,phone,linkedin_url,github_url,portfolio_url,personal_website,verified_experience_years,verified_skills,verified_roles,education,projects,certifications,summary,preferences,active_resume_version_id,id,singleton_key,version,created_at,updated_at) SELECT ($1::jsonb->>'full_name'),($1::jsonb->>'email'),($1::jsonb->>'phone'),($1::jsonb->>'linkedin_url'),($1::jsonb->>'github_url'),($1::jsonb->>'portfolio_url'),($1::jsonb->>'personal_website'),($1::jsonb->>'verified_experience_years')::double precision,$1::jsonb->'verified_skills',$1::jsonb->'verified_roles',$1::jsonb->'education',$1::jsonb->'projects',$1::jsonb->'certifications',($1::jsonb->>'summary'),$1::jsonb->'preferences',$3,$2,'primary',1,at,at FROM stamp ON CONFLICT (singleton_key) DO NOTHING
